import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    arr = [int(next(it)) for _ in range(n)]
    target = int(next(it))

    if n == 0:
        # array is empty, just output nothing
        return

    try:
        idx = arr.index(target)
    except ValueError:
        idx = -1

    if idx == -1:
        result = arr
    else:
        result = arr[:idx] + arr[idx+1:]

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
